solution.solution.cpp:
#include <algorithm>
#include <vector>

int positionOf(const std::vector<int>& values, int target)
{
    const auto it{ std::find(values.begin(), values.end(), target) };
    if (it == values.end())
    {
        return -1;
    }
    return static_cast<int>(it - values.begin());
}

unitTests:
TEST("found") { CHECK_EQ(positionOf({ 10, 20, 30, 40 }, 30), 2); CHECK_EQ(positionOf({ 10, 20, 30, 40 }, 10), 0); }
TEST("first of several") { CHECK_EQ(positionOf({ 5, 7, 7, 7 }, 7), 1); }
TEST("missing") { CHECK_EQ(positionOf({ 10, 20 }, 99), -1); CHECK_EQ(positionOf({}, 1), -1); }

